def plan_reminders(invoices, sent_reminders, today):
    key = json.dumps([_enc(invoices), _enc(sent_reminders), _enc(today)])
    out = TABLE.get(key)
    if out is None:
        return []
    if out[0] == "ok":
        return _dec(out[1])
    raise ValueError(out[1])
